let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { p = null; }
  msg.payload = p;                       // les nœuds suivants reçoivent un objet
}
flow.set('lastSeen', Date.now());
let motif = null;
if (typeof p !== 'object' || p === null) {
  motif = 'JSON invalide';
} else if (p.temperature === null || p.temperature === undefined) {
  motif = 'capteur temperature deconnecte (null)';
} else if (typeof p.temperature !== 'number' || p.temperature < -40 || p.temperature > 80) {
  motif = 'temperature hors plage : ' + p.temperature;
} else if (typeof p.vibration !== 'number' || p.vibration < 0 || p.vibration > 160) {
  motif = 'vibration hors plage : ' + p.vibration;
}
if (motif) {
  return [null, {topic: 'dashboard/validation', payload: 'DONNEE REJETEE : ' + motif}];
}
return [msg, null];

// Règle de décision : moyenne mobile sur N mesures valides
const N = 3;
const m = msg.payload;   // objet {temperature, vibration, statut}

// 1. Mémoriser les N dernières valeurs
let bt = flow.get('bufT') || [];
let bv = flow.get('bufV') || [];
bt.push(m.temperature);
bv.push(m.vibration);
if (bt.length > N) bt.shift();
if (bv.length > N) bv.shift();
flow.set('bufT', bt);
flow.set('bufV', bv);

// 2. Moyennes
const moy = a => a.reduce((s, x) => s + x, 0) / a.length;
const T = moy(bt);
const V = moy(bv);

// 3. Niveau brut selon les seuils
const rang = { NORMAL: 0, PREALERTE: 1, CRITIQUE: 2 };
const ancien = flow.get('niveau') || 'NORMAL';

let brut = 'NORMAL';
if (T >= 70 || V >= 2.6) brut = 'CRITIQUE';
else if (T >= 65 || V >= 2.0) brut = 'PREALERTE';

// 4. Hystérésis : on ne redescend que sous 60 °C et 2,0 m/s²
let nouveau = brut;
if (rang[brut] < rang[ancien]) {
    nouveau = (T < 60 && V < 2.0) ? 'NORMAL' : ancien;
}
flow.set('niveau', nouveau);

const detail = 'T moy=' + T.toFixed(1) + ' C, V moy=' + V.toFixed(2) + ' m/s2';

// Sortie 1 : niveau courant (affichage)
const sortie1 = { payload: nouveau };

// Sortie 2 : événement, seulement quand le niveau change
const sortie2 = (nouveau !== ancien)
    ? { topic: 'decision', payload: nouveau + ' : ' + detail }
    : null;

// Sortie 3 : commande OFF, seulement à l'entrée en CRITIQUE
const sortie3 = (nouveau === 'CRITIQUE' && ancien !== 'CRITIQUE')
    ? { payload: 'OFF' }
    : null;

return [sortie1, sortie2, sortie3];

// Surveillance : plus de mesures depuis plus de 40 s ?
const SEUIL_MS = 40000;
const last = flow.get('lastSeen');
const etatAvant = flow.get('etatLiaison') || 'INCONNU';

let etat;
let detail;
if (!last) {
    etat = 'EN ATTENTE';
    detail = 'aucune mesure recue depuis le demarrage';
} else {
    const age = Math.round((Date.now() - last) / 1000);
    if (age > SEUIL_MS / 1000) {
        etat = 'PERDUE';
        detail = 'aucune mesure depuis ' + age + ' s';
    } else {
        etat = 'OK';
        detail = 'derniere mesure il y a ' + age + ' s';
    }
}
flow.set('etatLiaison', etat);

msg.payload = etat;
msg.detail = detail;
msg.changement = (etat !== etatAvant);
return msg;

node.warn('Journal recoit : ' + msg.topic + ' | ' + msg._msgid);
const txt = (typeof msg.payload === 'object')
    ? JSON.stringify(msg.payload)
    : String(msg.payload);
const source = msg.topic || 'inconnu';
msg.payload = new Date().toISOString() + ';' + source + ';' +
    txt.replace(/[;\r\n]+/g, ' ') + '\n';
return msg;

const p = msg.payload;
const ts = (p.ts > 0) ? p.ts : Math.floor(Date.now() / 1000);
msg.payload = ts + ',' + p.temperature + ',' + p.vibration + ',' + p.statut + '\n';
return msg;

const p = msg.payload;
const dejaEnvoye = flow.get("offAuto") || false;

if (p.moyenne !== null && p.moyenne >= 72 && p.etat === "ATTENTION" && !dejaEnvoye) {
    flow.set("offAuto", true);
    return [
        { payload: "OFF" },
        {
            topic: "decision/prediction",
            payload: "ARRET PREVENTIF AUTOMATIQUE : moyenne " + p.moyenne + " C"
        }
    ];
}
if (p.moyenne !== null && p.moyenne < 65) flow.set("offAuto", false);
return [null, null];

const p = msg.payload;
const nb = v => (typeof v === 'number') ? v.toFixed(1) : '—';
let restant = '—';
if (typeof p.restant === 'number') {
    restant = Math.floor(p.restant / 60) + ' min ' + Math.round(p.restant % 60) + ' s';
}
// Sortie 6 : deux courbes pour le meme graphique (tableau = deux messages)
let courbes = [];
if (typeof p.moyenne === 'number')
    courbes.push({ topic: 'Moyenne (°C)', payload: p.moyenne });
if (typeof p.pente === 'number') {
    const pente = Math.max(-10, Math.min(10, p.pente));  // limite aux valeurs plausibles
    courbes.push({ topic: 'Pente (x3, base 40)', payload: 40 + pente * 3 });
}
return [
    { payload: p.etat || '—' },
    { payload: p.raison || '—' },
    { payload: nb(p.moyenne) },
    { payload: nb(p.pente) },
    { payload: restant },
    courbes.length ? [courbes] : null
];

const nomType = {
    'dashboard/commande': 'ACTION',
    'decision/prediction': 'ACTION',
    'dashboard/liaison': 'LIAISON',
    'usine/ligne1/esp32/etat': 'LIAISON',
    'dashboard/validation': 'REJET',
    'usine/ligne1/moteur/statut': 'ÉTAT',
    'usine/ligne1/moteur/defaut': 'DÉFAUT'
};

const ligne = String(msg.payload).replace(/\n/g, '');
// ANTI-DOUBLON SUR LA LIGNE COMPLETE : l'horodatage à la milliseconde rend chaque événement unique
const vues = flow.get('lignesVues') || [];
if (vues.includes(ligne)) return null;
vues.push(ligne);
flow.set('lignesVues', vues.slice(-50));
const parts = ligne.split(';');
const topic = parts[1] || '';
const message = parts.slice(2).join(' ');

// ignorer le défaut "aucun" (retained)
if (topic === 'usine/ligne1/moteur/defaut' && message.trim() === 'aucun') return null;

let type = nomType[topic] || topic;
if (topic === 'usine/ligne1/alertes') {
    type = message.startsWith('MOTEUR COUPE') ? 'DÉFAUT' : 'ALERTE';
}
if (message.includes('ordre distant')) type = 'ACTION';

// ANTI-DOUBLON : même source ET même message que la dernière valeur connue
const cle = topic + '|' + message;
const dernieres = flow.get('dernieresValeurs') || {};
const estEtat = ['usine/ligne1/moteur/statut',
                 'usine/ligne1/esp32/etat',
                 'usine/ligne1/moteur/defaut',
                 'dashboard/liaison'].includes(topic);
if (estEtat) {
    if (dernieres[topic] === message) return null;   // pas un vrai changement
    dernieres[topic] = message;
    flow.set('dernieresValeurs', dernieres);
}

const d = new Date(parts[0]);
const horo = isNaN(d) ? parts[0] : d.toLocaleString('fr-FR');

let liste = flow.get('journalAffiche') || [];
liste.unshift({ horodatage: horo, source: type, message: message });
if (liste.length > 20) liste = liste.slice(0, 20);
flow.set('journalAffiche', liste);

msg.payload = liste;
return [[ { payload: [] }, msg ]];    // d'abord une liste vide qui efface le tableau, puis la liste complète
